<?php $pageTitle='Customers';$subtitle='View registered customers and account activity without exposing passwords.';$active='Customers';require __DIR__.'/_layout.php';$rows=db()->query("SELECT u.id,u.name,u.phone,u.email,u.status,u.created_at,COUNT(o.id) order_count,COALESCE(SUM(CASE WHEN o.order_status<>'cancelled' THEN o.total_amount ELSE 0 END),0) spend FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE u.role='user' GROUP BY u.id ORDER BY u.id DESC")->fetchAll();?><div class="card"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Orders</th><th>Spend</th><th>Status</th><th>Joined</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=ae($r['name'])?></strong><br><small><?=ae($r['email'])?></small></td><td><?=ae($r['phone'])?></td><td><?=number_format((int)$r['order_count'])?></td><td>₹<?=number_format((float)$r['spend'],2)?></td><td><span class="pill <?=($r['status']==='active'?'green':'red')?>"><?=ae($r['status'])?></span></td><td><?=ae($r['created_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty">No customers found.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/_foot.php';?>
